window.VeilGardeData.files["Tests-VeilGardeInferenceTests"] = {"group":"Tests-VeilGardeInferenceTests","files":[{"path":"Tests/VeilGardeInferenceTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,31]],"header":{"lines":[1,8],"target":"VeilGardeInferenceTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1327,"scopes":[["E","Fixture",null,"",13,13,[13,13],31,null,-1,0,"a",[]],["f","crop",["_"],"static",20,20,[20,44],20,null,0,8,"a"],["v","weightsPresent",null,"static",27,27,[27,36],30,null,0,0,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Inference tests read by repo path: the two parity crops and VeilGarde's own route\n//        goldens for them, and whether the DINOv2 weights are present.\n//\n\nimport Foundation\nimport VeilGardeInference\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static func crop(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeInferenceTests/Fixtures/crops/\\(name)\") }\n\n    /// The parity fixtures too large for the repo (dino_parity.safetensors is 1.8 MB), in the work\n    /// area's parity/; VEILGARDE_PARITY_DIR names another folder.\n    static let parityDir = URL(fileURLWithPath: ProcessInfo.processInfo.environment[\"VEILGARDE_PARITY_DIR\"]\n        ?? WorkArea.resolve()?.parity.path ?? \"parity\")\n\n    static var weightsPresent: Bool {\n        ShippedBundle.registerWeightFolders()\n        return WeightLocator.shared.url(.dinov2Small) != nil\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/FusionLayoutTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,68]],"header":{"lines":[1,12],"target":"VeilGardeInferenceTests","what":[6,11],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1330,"scopes":[["X","InferenceMLXSuites",null,"",19,19,[19,29],68,null,-1,0,"a"],["S","FusionLayoutTests",null,"",20,21,[21,29],67,null,0,0,"a"],["f","oneSplit",["on","at","width"],"static",23,23,[23,91],28,[22,22],1,0,"a"],["f","bundle",["with"],"static",31,31,[31,81],43,[30,30],1,0,"a"],["f","layouts",[],"",45,46,[46,30],66,null,1,0,"a"]],"old":"","new":"//\n//  FusionLayoutTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The detector builds the fusion row in the layout its head's width names: a 777-column\n//        head reads the force-resized DINOv2 embedding after the plain one, and a 393-column head\n//        reads the capture values there; an 815-column head reads the warp residual's statistics\n//        after capture. Each head is one hand-built tree split on one column, at\n//        a threshold between what the two layouts would put in that column, inside a copy of the\n//        shipped bundle.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\nimport VeilWatermark\n\nextension InferenceMLXSuites {\n    @Suite(\"Fusion layouts\", .serialized, .enabled(if: Fixture.weightsPresent))\n    struct FusionLayoutTests {\n        /// One tree: −2 when `column` is under `threshold`, +2 otherwise, from a base score of 0.5.\n        static func oneSplit(on column: Int, at threshold: Float, width: Int) -> GBDTModel {\n            let tree = GBDTModel.Tree(id: 0, leftChildren: [1, -1, -1], rightChildren: [2, -1, -1], parents: [GBDTModel.Tree.rootParent, 0, 0],\n                                      splitIndices: [Int32(column), 0, 0], splitConditions: [threshold, -2, 2], baseWeights: [0, -2, 2],\n                                      defaultLeft: [0, 0, 0], splitType: [0, 0, 0], lossChanges: [1, 0, 0], sumHessian: [10, 5, 5], numFeature: width)\n            return GBDTModel(trees: [tree], baseScoreProbability: 0.5, featureCount: width)\n        }\n\n        /// The shipped bundle, copied, with its fusion head replaced and the manifest re-pinned.\n        static func bundle(with head: GBDTModel) throws -> (DetectorBundle, URL) {\n            let dir = FileManager.default.temporaryDirectory.appendingPathComponent(\"vg-layout-\\(UUID().uuidString)\")\n            try FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)\n            var manifest = ShippedBundle.manifest\n            for a in manifest.artifacts where a.role != .fusionHead {\n                try FileManager.default.copyItem(at: ShippedBundle.directory.appendingPathComponent(a.file), to: dir.appendingPathComponent(a.file))\n            }\n            try head.encodeXGBoostJSON().write(to: dir.appendingPathComponent(\"fusion_head.xgb.json\"))\n            manifest.artifacts.removeAll { $0.role == .fusionHead }\n            manifest.artifacts.append(try ModelBundle.record(.fusionHead, file: \"fusion_head.xgb.json\", in: dir))\n            try JSONCoding.write(manifest, to: dir.appendingPathComponent(BundleManifest.fileName))\n            return (try DetectorBundle.load(dir), dir)\n        }\n\n        @Test(\"each head's row is built in its own layout: column 384 is dino_norm's first value at 777 columns, capture's at 393\")\n        func layouts() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_fox.png\"))\n            let norm = try SemanticLens.normalizedEmbedding(cg)[0], cap = CaptureLens.features(cg).asVector[0]\n            #expect(norm != cap)\n            for (layout, right, wrong) in [(FusionLayout.bothReadings, norm, cap), (.dinoCapture, cap, norm)] {\n                let threshold = (right + wrong) / 2\n                let (bundle, dir) = try Self.bundle(with: Self.oneSplit(on: 384, at: threshold, width: layout.width))\n                defer { try? FileManager.default.removeItem(at: dir) }\n                let base = try #require(Detector.shared.detect(cgImage: cg, config: InferenceConfig(bundle: bundle)).result.routeDiagnostics?.baseP)\n                let want: Float = right < threshold ? 1 / (1 + Float(exp(2.0))) : 1 / (1 + Float(exp(-2.0)))\n                #expect(abs(base - want) < 1e-6, \"\\(layout.rawValue): base \\(base), want \\(want)\")\n            }\n            // An 815-column head reads the warp residual's first statistic, FR's mean, at column 777.\n            let fr = try VeilWatermark.ResidualStatistics.measure(cg)[0]\n            for (threshold, want) in [(fr - 1e-4, 1 / (1 + Float(exp(-2.0)))), (fr + 1e-4, 1 / (1 + Float(exp(2.0))))] {\n                let (bundle, dir) = try Self.bundle(with: Self.oneSplit(on: 777, at: threshold, width: FusionLayout.bothReadingsResidual.width))\n                defer { try? FileManager.default.removeItem(at: dir) }\n                let base = try #require(Detector.shared.detect(cgImage: cg, config: InferenceConfig(bundle: bundle)).result.routeDiagnostics?.baseP)\n                #expect(abs(base - want) < 1e-6, \"residual: base \\(base), want \\(want)\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeInferenceTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1335,"scopes":[["S","InferenceLinkTests",null,"",12,13,[13,26],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports the layers below it.\n//\n\nimport Testing\nimport VeilGardeInference\n\n@Suite(\"Inference links\")\nstruct InferenceLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeInferenceTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1337,"scopes":[["S","InferenceMLXSuites",null,"",20,21,[21,26],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under InferenceMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Inference: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct InferenceMLXSuites {}\n"},{"path":"Tests/VeilGardeInferenceTests/RouteGoldenTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,105]],"header":{"lines":[1,11],"target":"VeilGardeInferenceTests","what":[6,10],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1338,"scopes":[["f","leaves",["_","_"],"",18,18,[18,66],22,[17,17],-1,0,"a"],["f","compare",["_","_","tolerance"],"",26,26,[26,102],42,[24,25],-1,0,"a"],["X","InferenceMLXSuites",null,"",44,44,[44,29],105,null,-1,0,"a"],["S","RouteGoldenTests",null,"",45,46,[46,28],104,null,2,0,"a"],["f","routeJSON",["name"],"",47,48,[48,44],57,null,3,0,"a"],["f","schemaV3",[],"",59,60,[60,31],68,null,3,0,"a"],["f","screenshotHint",[],"",70,71,[71,37],77,null,3,0,"a"],["f","semanticRemoved",[],"",79,80,[80,38],87,null,3,0,"a"],["f","dinoParity",[],"",91,91,[91,33],103,null,3,0,"a"]],"old":"","new":"//\n//  RouteGoldenTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The full detector against VeilGarde's own route goldens (`veilgarde route --json` on the\n//        two parity crops with the shipped bundle of 2026-10-21): every label, route and structural\n//        field equal, every number within 1e-4 (DINOv2's matrix kernels move with Frigate's MLX\n//        revision by about 1e-5). The schema-v3 keys; the screenshot hint; the semantic chain\n//        removed; DINOv2 against the HF reference embeddings.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n/// Every leaf of a JSON value with its path.\nfunc leaves(_ value: Any, _ path: String = \"\") -> [(String, Any)] {\n    if let d = value as? [String: Any] { return d.keys.sorted().flatMap { leaves(d[$0]!, path.isEmpty ? $0 : \"\\(path).\\($0)\") } }\n    if let a = value as? [Any] { return a.enumerated().flatMap { leaves($1, \"\\(path)[\\($0)]\") } }\n    return [(path, value)]\n}\n\n/// Labels exact, numbers within `tolerance`, times_sec aside; returns the worst numeric difference and\n/// any mismatches.\nfunc compare(_ a: Data, _ b: Data, tolerance: Double) throws -> (worst: Double, mismatches: [String]) {\n    let kept: ((String, Any)) -> Bool = { !$0.0.hasPrefix(\"times_sec\") }\n    let x = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: a)).filter(kept))\n    let y = Dictionary(uniqueKeysWithValues: leaves(try JSONSerialization.jsonObject(with: b)).filter(kept))\n    var worst = 0.0\n    var mismatches = Array(Set(x.keys).symmetricDifference(y.keys)).sorted()\n    for key in Set(x.keys).intersection(y.keys) {\n        if let m = x[key] as? NSNumber, let n = y[key] as? NSNumber, CFGetTypeID(m) != CFBooleanGetTypeID() {\n            let d = abs(m.doubleValue - n.doubleValue)\n            worst = max(worst, d)\n            if d > tolerance { mismatches.append(\"\\(key): \\(m) vs \\(n)\") }\n        } else if \"\\(x[key]!)\" != \"\\(y[key]!)\" {\n            mismatches.append(\"\\(key): \\(x[key]!) vs \\(y[key]!)\")\n        }\n    }\n    return (worst, mismatches)\n}\n\nextension InferenceMLXSuites {\n    @Suite(\"Full detector goldens\", .serialized, .enabled(if: Fixture.weightsPresent))\n    struct RouteGoldenTests {\n        @Test(\"the routed result matches the golden: labels exact, numbers within 1e-4\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func routeJSON(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"\\(name).png\"))\n            let routed = try Detector.shared.detect(cgImage: cg, config: InferenceConfig())\n            #expect(routed.domain == .camera)\n            let ours = try ResultJSON.encode(routed.result, times: [], device: \"route\", route: routed.domain.rawValue)\n            let (worst, mismatches) = try compare(ours, Data(contentsOf: Fixture.crop(\"\\(name).route.json\")), tolerance: 1e-4)\n            #expect(mismatches.isEmpty, \"\\(mismatches.prefix(5))\")\n            #expect(worst < 1e-4, \"max |Δ| \\(worst)\")\n            #expect(routed.result.specialists?.map(\\.name) == [\"fusion\", \"art\", \"blur\", \"human\", \"capture\", \"semantic-tiles\"])\n        }\n\n        @Test(\"the result JSON is schema v3\")\n        func schemaV3() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_fox.png\"))\n            let routed = try Detector.shared.detect(cgImage: cg, config: InferenceConfig())\n            let json = try #require(JSONSerialization.jsonObject(with: ResultJSON.encode(routed.result, times: [], device: \"route\", route: \"camera\")) as? [String: Any])\n            #expect(Set(json.keys) == [\"bundle\", \"capture\", \"device\", \"image\", \"route\", \"route_diagnostics\", \"schema_version\", \"scorer\", \"semantic_tiles\",\n                                       \"specialists\", \"times_sec\", \"verdict\"])\n            #expect(json[\"schema_version\"] as? Int == 3 && json[\"scorer\"] as? String == \"fusion\")\n            #expect(routed.result.imageWidth == cg.width && routed.result.imageHeight == cg.height)\n        }\n\n        @Test(\"a screenshot hint routes to the content head\")\n        func screenshotHint() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_ben.png\"))\n            let routed = try Detector.shared.detect(cgImage: cg, config: InferenceConfig(), hint: .screenshot)\n            #expect(routed.domain == .screenshot)\n            #expect(routed.result.scorer == \"screenshot\")\n            #expect(routed.result.routeDiagnostics?.requestedHint == \"screenshot\" && routed.result.routeDiagnostics?.route == \"screenshot\")\n        }\n\n        @Test(\"removing the semantic chain runs no semantic probe\")\n        func semanticRemoved() throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.crop(\"crop_fox.png\"))\n            var config = InferenceConfig()\n            config.semanticResponsibility = .semanticRemoved\n            let r = try Detector.shared.detect(cgImage: cg, config: config).result\n            #expect(r.semanticTiles == nil && r.routeDiagnostics?.semanticEvaluated == false)\n            #expect(!(r.specialists ?? []).contains { $0.name == \"semantic-tiles\" })\n        }\n\n        @Test(\"DINOv2 reproduces the HF reference embeddings (cosine ≥ 0.999)\",\n              .enabled(if: FileManager.default.fileExists(atPath: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\").path)))\n        func dinoParity() throws {\n            let file = try SafetensorsFile(url: Fixture.parityDir.appendingPathComponent(\"dino_parity.safetensors\"))\n            let bases = Set(file.names.filter { $0.hasSuffix(\".pixels\") }.map { String($0.dropLast(7)) }).sorted()\n            #expect(!bases.isEmpty)\n            for base in bases {\n                let emb = try SemanticLens.embedding(pixels: try file.float32(\"\\(base).pixels\"))\n                let ref = try file.float32(\"\\(base).emb\")\n                var dot: Float = 0, na: Float = 0, nb: Float = 0\n                for i in 0..<emb.count { dot += emb[i] * ref[i]; na += emb[i] * emb[i]; nb += ref[i] * ref[i] }\n                let cos = dot / (na.squareRoot() * nb.squareRoot())\n                #expect(cos >= 0.999, \"\\(base): cosine \\(cos)\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeInferenceTests/ShippedBundleTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,33]],"header":{"lines":[1,8],"target":"VeilGardeInferenceTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1347,"scopes":[["S","ShippedBundleTests",null,"",14,15,[15,26],33,null,-1,0,"a"],["f","defaults",[],"",16,17,[17,27],26,null,0,0,"a"],["f","combiner",[],"",28,29,[29,27],32,null,0,0,"a"]],"old":"","new":"//\n//  ShippedBundleTests.swift\n//  VeilGardeInferenceTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The shipped bundle verifies, holds the fusion head and the combiner trained on 2026-10-21\n//        and the six heads, and the detector's defaults point into it at its one operating point.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeInference\n\n@Suite(\"Shipped bundle\")\nstruct ShippedBundleTests {\n    @Test(\"the shipped bundle verifies and the defaults point into it\")\n    func defaults() throws {\n        let bundle = try ShippedBundle.verified()\n        #expect(bundle.manifest.artifacts.count == 8 && bundle.manifest.weights.count == 3)\n        #expect(bundle.manifest.artifact(.fusionHead)?.sha256 == \"b142e661c609070a7838fb015ae47a8b9ccce2ab1d539c3dac29afadc48b8f9e\")\n        #expect(bundle.manifest.artifact(.combiner)?.file == \"stack_combiner_v3.json\")\n        #expect(bundle.manifest.artifact(.head, head: .artPair) == nil && bundle.manifest.artifact(.head, head: .cgi) == nil)\n        let config = InferenceConfig()\n        #expect(config.bundle.isShipped && config.decision == .fusion && config.dinoVariant == .small && config.semanticResponsibility == .control)\n        #expect(config.bundle.url(.fusionHead)?.lastPathComponent == \"fusion_head.xgb.json\")\n    }\n\n    @Test(\"the shipped combiner loads without a noiseprint term\")\n    func combiner() throws {\n        let c = try #require(HeadRegistry.shared.combiner(in: .shipped))\n        #expect(c.wGen.count == 3 && c.pairAdjudicates == false)\n    }\n}\n"}]};
